fun modInv(x: Long): Long = modPow(x, MOD - 2)

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toLong()
    val k = st.nextToken().toInt()

    // Factorize n (n <= 1e15)
    var tmp = n
    val primes = mutableListOf<Long>()
    val exps = mutableListOf<Int>()
    var d = 2L
    while (d * d <= tmp) {
        if (tmp % d == 0L) {
            var cnt = 0
            while (tmp % d == 0L) {
                tmp /= d
                cnt++
            }
            primes.add(d)
            exps.add(cnt)
        }
        d += if (d == 2L) 1L else 2L
    }
    if (tmp > 1L) {
        primes.add(tmp)
        exps.add(1)
    }

    // Precompute factorials up to max exponent
    val maxE = exps.maxOrNull() ?: 0
    val fact = LongArray(maxE + 1)
    val invFact = LongArray(maxE + 1)
    fact[0] = 1L
    for (i in 1..maxE) fact[i] = modMul(fact[i - 1], i.toLong())
    invFact[maxE] = modInv(fact[maxE])
    for (i in maxE downTo 1) {
        invFact[i - 1] = modMul(invFact[i], i.toLong())
    }

    fun comb(nc: Int, rc: Int): Long {
        if (rc < 0 || rc > nc) return 0L
        return modMul(fact[nc], modMul(invFact[rc], invFact[nc - rc]))
    }

    // Precompute binomial coefficients C(k, t) for t=0..k
    val Ckt = LongArray(k + 1)
    for (t in 0..k) {
        // compute C(k, t) via multiplicative formula
        var res = 1L
        var r = t
        if (r > k - r) r = k - r
        var num = 1L
        var den = 1L
        for (i in 1..r) {
            num = modMul(num, (k - r + i).toLong())
            den = modMul(den, i.toLong())
        }
        res = modMul(num, modInv(den))
        Ckt[t] = res
    }

    var answer = 1L

    for (idx in primes.indices) {
        val p = primes[idx] % MOD
        val e = exps[idx]

        // dp[t][j] for t=0..k, j=0..e
        val dp = Array(k + 1) { LongArray(e + 1) }
        dp[0][e] = 1L

        for (step in 1..k) {
            val prev = dp[step - 1]
            val cur = dp[step]
            for (j in 0..e) cur[j] = 0L
            for (j in 0..e) {
                val valPrev = prev[j]
                if (valPrev == 0L) continue
                val inv = modInv((j + 1).toLong())
                for (x in 0..j) {
                    cur[x] = modAdd(cur[x], modMul(valPrev, inv))
                }
            }
        }

        // Precompute p^j
        val powP = LongArray(e + 1)
        powP[0] = 1L
        for (j in 1..e) powP[j] = modMul(powP[j - 1], p)

        // Compute E_p(k) = sum_j dp[k][j] * p^j
        var Ep = 0L
        for (j in 0..e) {
            if (dp[k][j] != 0L) {
                Ep = modAdd(Ep, modMul(dp[k][j], powP[j]))
            }
        }

        // Compute E_p(k)^{C(k,t)} product over t
        // But we already have Ep as expectation after k steps for this prime
        // Actually we need Ep only once; expectation for full n is product over primes of Ep
        answer = modMul(answer, Ep)
    }

    println(answer % MOD)
}

